import{z as o,x as n,o as A,c as d,q as s,j as r,D as B,d as a,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"存储深化收束","description":"","frontmatter":{"title":"存储深化收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/st-map.md","filePath":"cs/st-map.md","lastUpdated":1791413859000}'),F={name:"cs/st-map.md"};function p(c,E,m,D,C,h){const t=n("Mermaid");return A(),d("div",null,[E[2]||(E[2]=s('<h1 id="存储深化收束" tabindex="-1">存储深化收束 <a class="header-anchor" href="#存储深化收束" aria-label="Permalink to &quot;存储深化收束&quot;">​</a></h1><div class="epigraph"><p>存储系统的设计不是在好坏之间选，而是在三本放大账之间转移成本；能读懂转移发生在哪一层的人，才谈得上选型。</p><footer>—— 据 O&#39;Neil et al., 1996；Graefe, 2010；Agrawal et al., 2008；Melnik et al., 2010 各自的取舍陈述整理</footer></div><p><a href="/cs/st-distributed-cases">上一课</a>用四份答卷把单机的页、日志与格式带进集群。本课程到此收束：本课把七课与主干拼成三张总账——放大账、合同账、层次账，并给出一个通用的读法：先问成本转移到哪了，再问合同签给谁，最后问层次插在哪。主干课钉过单点机制，深化课补的是机制之间的账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>决策变量从来不是「哪个结构最好」，而是四组：读改写比与负载形状（点查、范围、扫描、嵌套分析）、介质与耐久（盘会擦写几次、随机写贵几倍）、规模与一致性（单机到集群、最终到外部一致）、可接受的运维复杂度。<a href="/cs/st-lsm-deep">LSM 的深入</a>服务写多读少的点查，<a href="/cs/st-btree-implementation">B+ 树的实现细节</a>服务读路径短而随机的更新，<a href="/cs/st-ssd-ftl">SSD 与 FTL</a> 决定前两家每页写被乘几倍，<a href="/cs/st-parquet-anatomy">Parquet 解剖</a>与<a href="/cs/st-compressed-columnar">压缩列存</a>服务扫描为主的列式分析，<a href="/cs/st-cache-tiers">缓存的层次</a>把单机各层拼图，<a href="/cs/st-distributed-cases">分布式存储的案例</a>把拼图带上集群。缺一课都不成图。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三张账的读法。放大账：写、读、空间三种放大在结构（LSM 形状）、实现（B+ 填充率与分隔键）、介质（FTL 的 WAF）三层各自记账又互相作用——LSM 的顺序刷盘讨好 FTL 的 log 区，随机 UUID 主键惩罚 FTL 的 GC，也惩罚 B+ 的页占用率；压缩把读放大的字节变成解压的周期。<span class="marginnote">常见误区：只看一层账就下结论——LSM 在结构层把随机写顺序化了，到了 FTL 层随机小写照样被 GC 乘上好几倍。三层账必须分记再合并，否则结论方向对、数值全错。</span>账要先在每层分开记，再合并算总账，只看任何一层都会得出方向正确的错误结论。合同账：本课程每课都在签合同——页（引擎对介质）、文件格式（引擎对存储）、映射（LBA 对物理页）、缓存（层对层）、时间戳（事务对时钟）。合同越往下越难重签：FTL 固化在盘里，文件格式固化在数据湖里，改合同的成本就是迁移的成本。<span class="marginnote">直觉类比：合同像装修时埋进墙里的水管——页、映射、格式一旦定下，改一处要砸开整面墙；越往下的合同（FTL 固化在盘里）重签成本越接近换整套设备。</span>层次账：每一层缓存的准入、旁路与写序，每一层结构的插入判据（比下层快得多、比上层大得多、有人为替换负责）。</p>',7)),(A(),r(i,null,{default:B(()=>[l(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%B4%9F%E8%BD%BD%E6%98%AF%E4%BB%80%E4%B9%88%EF%BC%9F%22%5D%20--%3E%20OLTP%5B%22%E7%82%B9%E6%9F%A5%E4%B8%8E%E6%9B%B4%E6%96%B0%E5%A4%9A%22%5D%0A%20%20Q%20--%3E%20OLAP%5B%22%E6%89%AB%E6%8F%8F%E4%B8%8E%E8%81%9A%E5%90%88%E5%A4%9A%22%5D%0A%20%20OLTP%20--%3E%20C1%5B%22%E8%AF%BB%E5%86%99%E6%AF%94%E5%AE%9A%E5%BD%A2%E7%8A%B6%EF%BC%9ALSM%20%E6%88%96%20B%2B%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E4%BB%8B%E8%B4%A8%E6%94%B6%E7%A8%8E%EF%BC%9AWAF%20%E4%B8%8E%E5%AF%BF%E5%91%BD%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20OLAP%20--%3E%20F1%5B%22%E5%88%87%E5%88%97%E4%B8%8E%E6%8E%92%E5%BA%8F%EF%BC%9A%E8%A1%8C%E7%BB%84%E4%B8%8E%E7%BC%96%E7%A0%81%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E7%A0%81%E5%9F%9F%E6%89%A7%E8%A1%8C%EF%BC%9A%E5%BB%B6%E8%BF%9F%E7%89%A9%E5%8C%96%22%5D%0A%20%20C2%20--%3E%20CL%5B%22%E4%B8%8A%E9%9B%86%E7%BE%A4%EF%BC%9A%E6%8C%89%E5%9B%9B%E9%97%AE%E9%97%AE%E5%8D%B7%E9%80%89%E6%A1%88%E4%BE%8B%22%5D%0A%20%20F2%20--%3E%20CL%0A%20%20CL%20--%3E%20END%5B%22%E4%B8%89%E8%B4%A6%E5%A4%8D%E6%A0%B8%EF%BC%9A%E6%94%BE%E5%A4%A7%E3%80%81%E5%90%88%E5%90%8C%E3%80%81%E5%B1%82%E6%AC%A1%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("贯穿课程的机制母题有三个。摊销固定成本：与高性能网络课同一句话——LSM 的顺序刷盘把随机页写换成一次付清的归并带宽，批量装载把分裂税一次付清，ZNS 把 GC 的账整体搬回主机；凡是「每次都付的小钱」，都值得问能否「一次付清」。"),e("span",{class:"marginnote"},"数字实例：每次随机写 4 KiB，改成凑满 64 页后一次顺序写 256 KiB，单次寻址开销摊到每页就降为原来的约 1/64——摊销固定成本就是用批量把「每次付的小钱」除以批量。"),a("顺序化：LSM、LFS、FTL 的 log 区、排序的列存、自底向上建树，是同一个母题在五层的五个名字；顺序化的对手永远是随机访问，识别负载里谁是随机的那一方，就找到了设计的第一杠杆。排序与局部性：分隔键截断靠比较语义、列存的统计跳过靠数据局部性、编码收益靠有序度、缓存命中靠访问局部性——局部性是这套系统里唯一反复兑现的免费午餐，所有换它的成本（排序、聚簇、维护）都在写入端明码标价。")],-1)),(A(),r(i,null,{default:B(()=>[l(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E9%80%BB%E8%BE%91%E5%86%99%201%20%E9%A1%B5%22%5D%20--%3E%20S%5B%22%E7%BB%93%E6%9E%84%E5%B1%82%EF%BC%9ALSM%20%E5%BD%92%E5%B9%B6%E9%87%8D%E5%86%99%22%5D%0A%20%20W%20--%3E%20I%5B%22%E5%AE%9E%E7%8E%B0%E5%B1%82%EF%BC%9AB%2B%20%E5%88%86%E8%A3%82%E4%B8%8E%E5%A1%AB%E5%85%85%E7%8E%87%22%5D%0A%20%20W%20--%3E%20M%5B%22%E4%BB%8B%E8%B4%A8%E5%B1%82%EF%BC%9AFTL%20%E6%98%A0%E5%B0%84%E4%B8%8E%20GC%22%5D%0A%20%20S%20--%3E%20SA%5B%22%E5%86%99%E6%94%BE%E5%A4%A7%20%C3%97T%C2%B7L%22%5D%0A%20%20I%20--%3E%20IA%5B%22%E5%8D%A0%E7%A8%8E%E7%8E%87%E9%9A%8F%E6%8F%92%E5%85%A5%E5%BA%8F%EF%BC%9A%E5%8D%8A%E6%BB%A1%E5%88%B0%E8%BF%91%E6%BB%A1%22%5D%0A%20%20M%20--%3E%20MA%5B%22%E9%9A%8F%E6%9C%BA%E5%86%99%E8%A2%AB%E6%93%A6%E5%86%99%E5%9D%97%E5%80%8D%E6%95%B0%E6%94%BE%E5%A4%A7%22%5D%0A%20%20SA%20--%3E%20TOT%5B%22%E5%90%88%E5%B9%B6%E6%80%BB%E8%B4%A6%EF%BC%9A%E5%90%84%E5%B1%82%E7%9B%B8%E4%B9%98%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20IA%20--%3E%20TOT%0A%20%20MA%20--%3E%20TOT%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=s('<p><span class="marginnote">跨课程呼应：网络课的「每下移一层，固定税改固定成本」与本课程「放大成本在层间转移」是同一原理的两种记账；量化栏的执行课把它写成行情数据的函数——三栏共用的是摊销与局部性，不是同一批结论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不写云厂商产品选型与价格对照，不进纠删码的数学与一致性理论的证明，不展开向量化执行引擎的完整实现；安全（加密、多租户隔离）与备份恢复各有专课。深化课的主张始终是读法：机制在主干，账在这里。本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三张账：放大账在结构、实现、介质三层分记再合并；合同账看签给谁、重签多贵；层次账看准入、旁路、写序。</li><li>摊销固定成本与网络课同源：把每次付的小钱改写成一次付清的大钱。</li><li>顺序化是第一母题：LSM、LFS、FTL、列存排序、批量装载是它在五层的名字。</li><li>局部性是唯一的免费午餐，成本在写入端明码标价。</li><li>出处：O&#39;Neil et al. 1996；Graefe 2010；Agrawal et al. 2008；Melnik et al. 2010；据各文献取舍陈述整理。</li></ul>',5))])}const L=o(F,[["render",p]]);export{f as __pageData,L as default};
